        a, b = grid[:row_div], grid[row_div + 1:]
        height = min(len(a), len(b))
        a, b = a[:height], b[:height]
        # The first panel's background and sparse foreground identify its noise.
        panel_bg = Counter(v for row in a for v in row).most_common(1)[0][0]
        target = next(v for row in a for v in row if v != panel_bg)
        out = [[target] * w for _ in range(height)]
        for r in range(height):
            for c in range(w):
