 "content": "from collections import Counter


def transform(grid):
    """Keep the unique color shared by two panels, marking its aligned overlap."""
    h = len(grid)
    w = max(map(len, grid))
    if not h or not w:
        return []

    overall_bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Displayed ARC fixtures can omit trailing background cells; restore the
    # rectangular grid before finding a centered divider.
    grid = [row + [overall_bg] * (w - len(row)) for row in grid]

    candidates = []

    # Each divider splits the grid into equally sized panels. Checking equal
    # dimensions prevents uniform background rows/columns inside a panel from
    # being mistaken for the separator.
    for c in range(w):
        sep = grid[0][c]
        if sep == overall_bg or any(row[c] != sep for row in grid):
            continue
        left_w, right_w = c, w - c - 1
        if left_w == right_w and left_w > 0:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            shared = {v for row in left for v in row} & {v for row in right for v in row}
            if len(shared) == 1:
                candidates.append((0, abs(c - w // 2), left, right, next(iter(shared))))

    for r in range(h):
        sep = grid[r][0]
        if sep == overall_bg or any(v != sep for v in grid[r]):
            continue
        top_h, bottom_h = r, h - r - 1
        if top_h == bottom_h and top_h > 0:
            top, bottom = grid[:r], grid[r + 1:]
            shared = {v for row in top for v in row} & {v for row in bottom for v in row}
            if len(shared) == 1:
                candidates.append((1, abs(r - h // 2), top, bottom, next(iter(shared))))

    if not candidates:
        raise ValueError("centered separator with one shared panel color not found")

    # Prefer the centered divider; vertical and horizontal splits are exclusive
    # for the supplied task examples.
    _, _, first, second, target = min(candidates, key=lambda item: (item[1], item[0]))
    panel_h = len(first)
    panel_w = min(min(map(len, first)), min(map(len, second)))
    return [
        [3 if first[r][c] == target and second[r][c] == target else target
         for c in range(panel_w)]
        for r in range(panel_h)
    ]


